## Why This Is Asked
This problem tests the ability to model selections of multiple disjoint subarrays with an exact count — a common dynamic programming pattern in interviews.

## Key Concepts
- **DP on prefix**: State dp[i][t] tracks the best total using the first i elements with exactly t subarrays
- **Prefix sums**: Enable O(1) calculation of any subarray sum
- **Backpointers**: Store decisions to reconstruct the chosen subarrays
- **Edge cases**: Handle when n < k or when all values are negative

## Code Example
```javascript
function maxKSubarrays(A, k) {
  const n = A.length;
  const pref = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) pref[i] = pref[i - 1] + A[i - 1];

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const prev = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      if (dp[i - 1][t] >= dp[i][t]) {
        dp[i][t] = dp[i - 1][t];
        prev[i][t] = { skip: true };
      }
      for (let l = 1; l <= i; l++) {
        if (t > 0 && dp[l - 1][t - 1] !== -Infinity) {
          const val = dp[l - 1][t - 1] + (pref[i] - pref[l - 1]);
          if (val > dp[i][t]) {
            dp[i][t] = val;
            prev[i][t] = { skip: false, l, t: t - 1 };
          }
        }
      }
    }
  }

  const result = [];
  let i = n, t = k;
  while (i > 0 && t > 0) {
    const p = prev[i][t];
    if (p.skip) { i--; continue; }
    result.push([p.l, i]);
    i = p.l - 1; t = p.t;
  }
  return { value: dp[n][k], subarrays: result.reverse() };
}
```

## Why This Is Asked
This problem tests understanding of dynamic programming with non-overlapping segments where the segment value has a quadratic structure. It challenges candidates to handle state transitions, reconstruction, and complexity analysis systematically.

## Key Concepts
- DP over prefix arrays with block count tracking
- Transition by considering all possible block endpoints
- Prefix sum optimization for O(1) subarray sum queries
- Backpointers for optimal solution reconstruction
- Time-space trade-off analysis

## Code Implementation
```javascript
function maxSubarrayValue(A, k) {
  const n = A.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + A[i];
  }

  const dp = Array(n + 1).fill().map(() => Array(k + 1).fill(-Infinity));
  const prevStart = Array(n + 1).fill().map(() => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      // Skip i
      if (dp[i-1][t] > dp[i][t]) {
        dp[i][t] = dp[i-1][t];
        prevStart[i][t] = prevStart[i-1][t];
      }

      // End block at i
      for (let j = 1; j <= i; j++) {
        const blockValue = (prefix[i] - prefix[j-1]) * (i-j+1);
        const candidate = dp[j-1][t-1] + blockValue;
        if (candidate > dp[i][t]) {
          dp[i][t] = candidate;
          prevStart[i][t] = j;
        }
      }
    }
  }

  // Reconstruction
  const result = [];
  let currI = n, currT = k;
  while (currT > 0 && currI > 0) {
    const start = prevStart[currI][currT];
    if (start !== -1 && start !== prevStart[currI-1][currT]) {
      result.unshift([start-1, currI-1]);
      currI = start - 1;
      currT--;
    } else {
      currI--;
    }
  }

  return { maxValue: dp[n][k], subarrays: result };
}
```

